  feedback_positive_highlights = '{"хороший уровень подготовки","профессионализм преподавателей","сильная практическая база"}',
  feedback_negative_highlights = '{"нехватка аудиторий и оснащения","часть преподавателей оторвана от клинической практики"}',
  feedback_based_on_count = 6, feedback_generated_at = now(), updated_at = now()
where name = 'Северный государственный медицинский университет' and city = 'Архангельск';

